      de: ["Gegründet im Jahr 1989", "Beinhaltet 42 Seen", "Wigry-See ist 73 m tief", "Schutzgebiet für über 200 Vogelarten"],
      hu: ["1989-ben alapították", "42 tavat foglal magában", "A Wigry-tó 73 méter mély", "Több mint 200 madárfaj védett területe"],
