      de: ["Das Schutzgebiet integriert mehr als 40 eiszeitliche Seen in sein Ökosystem", "Der Wigry-See erreicht beachtliche Tiefen von bis zu 73 Metern", "Beherbergt weit über 250 aktive Biberburgen und zahllose Dammbauten", "Die Kanuroute auf der Czarna Hańcza gilt als eine der landschaftlich reizvollsten Polens", "Papst Johannes Paul II. verbrachte hier im Jahr 1999 einige Tage der Besinnung", "Das Gebiet ist Heimat des extrem seltenen und scheuen Eurasischen Fischotters", "Die komplexen Torfmoore um den See schützen eiszeitliche botanische Relikte"],
      hu: [],
