      en: [],
      es: ["El Orientarium inaugurado en 2022 abarca una superficie gigantesca de más de 33.000 metros cuadrados", "El túnel submarino acristalado en el tanque de tiburones es, con 26 metros, el más largo de Polonia", "La moderna casa de elefantes cuenta con una piscina cubierta profunda para observar a los elefantes nadando", "Participa en el programa de cría EEP para la conservación del amenazado león asiático", "Se cuenta entre las atracciones turísticas de más rápido crecimiento en Polonia Central", "El zoo se encuentra enclavado en el histórico y boscoso Parque Zdrowie (Parque de la Salud)", "Alberga una notable colonia de orangutanes de Borneo, en grave peligro de extinción"],
      pt: ["O Orientarium inaugurado em 2022 abrange uma área gigantesca de mais de 33.000 metros quadrados", "O túnel subaquático envidraçado no tanque dos tubarões é, com 26 metros, o mais longo da Polónia", "A moderna casa dos elefantes dispõe de uma piscina interior profunda para observar elefantes a nadar", "Envolve-se no programa de criação EEP para a preservação do ameaçado leão-asiático", "É uma das atrações turísticas que mais cresce na Polónia Central", "O jardim zoológico está inserido no histórico e arborizado Parque Zdrowie", "Abriga uma colónia notável de orangotangos-de-bornéu, em perigo crítico de extinção"],
      fr: ["L'Orientarium ouvert en 2022 couvre une superficie gigantesque de plus de 33 000 mètres carrés", "Le tunnel sous-marin vitré du bassin des requins est, avec 26 mètres, le plus long de Pologne", "La maison des éléphants moderne dispose d'un bassin intérieur profond pour observer les éléphants nager", "S'engage dans le programme d'élevage EEP pour la conservation du lion d'Asie menacé", "Compte parmi les attractions touristiques à la croissance la plus rapide du centre de la Pologne", "Le zoo est niché dans le parc historique et boisé de Zdrowie (Parc de la Santé)", "Abrite une colonie remarquable d'orangs-outans de Bornéo, gravement menacés"],
