    imageHint: "Fire salamander in Gorce forest",
    descriptionAdvanced: {
      de: "Der Gorce-Nationalpark schützt das zentrale Massiv der Gorce-Berge, eines malerischen Teils der Westkarpaten im Süden Polens. Charakteristisch für diese Landschaft ist der dramatische Kontrast zwischen dichten, dunklen Urwäldern aus Karpatenbuchen und Fichten, die die steilen Hänge bedecken, und den weitläufigen, sonnigen Bergwiesen auf den Kammlagen. Diese hochgelegenen Wiesen, im lokalen Dialekt 'Hale' genannt, verdanken ihre Entstehung der jahrhundertelangen traditionellen Schafzucht der walachischen Hirten. Heute sind diese Lichtungen von unschätzbarem botanischen Wert, da sie im Frühsommer in ein farbenprächtiges Meer aus seltenen Orchideen, Krokussen und Gladiolen verwandelt werden. In den feuchten und schattigen Bachtälern des Parks findet man zudem den idealen Lebensraum für den leuchtend gelb-schwarz gemusterten Feuersalamander, der als Symboltier des Parks allgegenwärtig ist. Für Wanderer bietet der Park, abseits des Massentourismus der Tatra, unberührte Pfade und weite Ausblicke.",
      hu: "A Gorce Nemzeti Park a Gorce-hegység központi masszívumát védi, amely a Nyugati-Kárpátok egy festői része Dél-Lengyelországban. E táj jellegzetessége a meredek lejtőket borító sűrű, sötét, kárpáti bükkből és lucfenyőből álló őserdők, valamint a gerinceken elterülő tágas, napfényes hegyi rétek közötti drámai kontraszt. Ezek a magasan fekvő rétek, amelyeket a helyi dialektusban 'Hale'-nak neveznek, a vlach pásztorok évszázados hagyományos juhtenyésztésének köszönhetik létrejöttüket. Ma ezek a tisztások felbecsülhetetlen botanikai értéket képviselnek, mivel kora nyáron ritka orchideák, krókuszok és kardvirágok színpompás tengerévé változnak. A park nedves és árnyékos patakvölgyeiben található ráadásul a ragyogó sárga-fekete mintás foltos szalamandra ideális élőhelye, amely a park címerállataként mindenütt jelen van. A túrázók számára a park a Tátra tömegturizmusától távol eső, érintetlen ösvényeket és tágas kilátást kínál.",
      ro: "Parcul Național Gorce protejează masivul central al Munților Gorce, o parte pitorească a Carpaților Occidentali din sudul Poloniei. Caracteristic acestui peisaj este contrastul dramatic dintre pădurile virgine dese și întunecate de fagi carpatici și molizi care acoperă pantele abrupte, și pajiștile montane însorite și extinse de pe creste. Aceste pajiști aflate la mare altitudine, numite 'Hale' în dialectul local, își datorează existența secolelor de creștere tradițională a oilor de către păstorii valahi. Astăzi, aceste poieni sunt de o valoare botanică inestimabilă, deoarece la începutul verii se transformă într-o mare colorată de orhidee rare, brândușe și gladiole. În văile umede și umbroase ale pâraielor din parc se află, de asemenea, habitatul ideal pentru salamandra de foc, cu modelul ei strălucitor galben-negru, care este omniprezentă ca animal simbol al parcului. Pentru drumeți, parcul oferă poteci neatinse și priveliști largi, departe de turismul de masă din Tatra.",
      en: "Gorce National Park protects the central massif of the Gorce Mountains, a picturesque section of the Western Carpathians in southern Poland. This landscape is characterized by the dramatic contrast between the dense, dark primeval forests of Carpathian beech and spruce that blanket the steep slopes, and the expansive, sunlit mountain meadows stretching across the ridges. These high-altitude meadows, known locally as 'Hale', owe their creation to centuries of traditional sheep farming by Vlach shepherds. Today, these clearings are of inestimable botanical value, transforming in early summer into a brilliantly colored sea of rare orchids, crocuses, and gladioli. Furthermore, the damp and shaded stream valleys of the park provide the ideal habitat for the strikingly yellow-and-black patterned fire salamander, which is ubiquitous as the park's symbol. For hikers, the park offers pristine trails and sweeping vistas, far removed from the mass tourism of the nearby Tatras.",
      es: "El Parque Nacional de Gorce protege el macizo central de las montañas Gorce, una parte pintoresca de los Cárpatos Occidentales en el sur de Polonia. Esta región se caracteriza por el drástico contraste entre los densos y oscuros bosques primigenios de abetos y hayas de los Cárpatos, que cubren las laderas empinadas, y las extensas y soleadas praderas de montaña en las crestas. Estas praderas de altura, llamadas 'Hale' en el dialecto local, deben su origen a siglos de cría tradicional de ovejas por parte de los pastores valacos. Hoy en día, estos claros tienen un valor botánico inestimable, ya que a principios de verano se transforman en un mar de colores de orquídeas raras, azafranes y gladiolos. En los valles de los arroyos, húmedos y sombreados, se encuentra el hábitat ideal para la salamandra común, de patrón amarillo y negro, omnipresente como animal símbolo del parque. Para los excursionistas, el parque ofrece senderos vírgenes y amplias vistas, lejos del turismo de masas de los Tatra.",
      pt: "O Parque Nacional de Gorce protege o maciço central das montanhas Gorce, uma parte pitoresca dos Cárpatos Ocidentais no sul da Polónia. Característico desta paisagem é o contraste dramático entre as florestas densas e escuras de faias e abetos e os extensos prados de montanha soalheiros nos cumes. Estes prados de altitude, chamados 'Hale', devem a sua origem a séculos de pastoreio tradicional dos pastores valacos. Hoje, estas clareiras têm um valor botânico inestimável, transformando-se num mar colorido de orquídeas raras, crocus e gladíolos. Nos vales húmidos dos ribeiros, encontra-se o habitat ideal para a salamandra-de-fogo, que é omnipresente como símbolo do parque. Para os caminhantes, o parque oferece trilhos intocados e vistas amplas, longe do turismo de massa dos Tatra.",
      fr: "Le parc national de Gorce protège le massif central des monts Gorce, une partie pittoresque des Carpates occidentales dans le sud de la Pologne. Ce paysage se caractérise par le contraste dramatique entre les forêts primaires denses et sombres de hêtres et d'épicéas des Carpates, qui couvrent les pentes escarpées, et les vastes prairies de montagne ensoleillées sur les crêtes. Ces prairies d'altitude, appelées « Hale » en dialecte local, doivent leur origine à des siècles d'élevage traditionnel de moutons par les bergers valaques. Aujourd'hui, ces clairières ont une valeur botanique inestimable, car elles se transforment au début de l'été en une mer de couleurs composée d'orchidées rares, de crocus et de glaïeuls. Dans les vallées humides et ombragées des ruisseaux du parc, on trouve l'habitat idéal pour la salamandre tachetée au motif jaune et noir éclatant, omniprésente en tant qu'animal symbole du parc. Pour les randonneurs, le parc offre des sentiers préservés et de vastes panoramas, loin du tourisme de masse des Tatras.",
    },
