      de: ["Das Wappentier des Parks, der auffällige Feuersalamander, kommt hier extrem häufig vor", "Der höchste Gipfel im Nationalpark ist der bewaldete Turbacz mit 1.310 Metern", "Über 50 unberührte Gebirgsbäche durchschneiden die bewaldeten Hänge des Parks", "Beheimatet dichte Bestände seltener Auerhühner und Haselhühner in den Kammlagen", "Die alten Holzhirtenhütten ('Szałasy') zeugen von der historischen Walachen-Kultur", "Die Bergwiese Jaworzyna Kamienicka ist berühmt für ihre spektakuläre Frühlingskrokusblüte", "Verzeichnet eine der größten Populationen des Karpatenluchses in den Beskiden"],
