      es: ["El animal del escudo, la llamativa salamandra común, es extremadamente frecuente aquí", "El pico más alto del parque nacional es el Turbacz, cubierto de bosque, con 1.310 metros", "Más de 50 arroyos de montaña vírgenes atraviesan las laderas boscosas del parque", "Hogar de densas poblaciones de urogallos y grévoles en las zonas de cresta", "Las antiguas cabañas de madera de los pastores ('Szałasy') dan fe de la histórica cultura valaca", "La pradera de montaña Jaworzyna Kamienicka es famosa por su espectacular floración de azafrán en primavera", "Registra una de las mayores poblaciones del lince de los Cárpatos en los Beskides"],
      pt: ["O animal símbolo do parque, a salamandra-de-fogo, é extremamente comum aqui", "O pico mais alto do parque nacional é o Turbacz, arborizado, com 1.310 metros", "Mais de 50 ribeiros de montanha imaculados atravessam as encostas arborizadas do parque", "Acolhe populações densas de tetrazes e galinhas-do-mato nas cristas", "As antigas cabanas de madeira dos pastores ('Szałasy') testemunham a cultura valaca histórica", "O prado de montanha Jaworzyna Kamienicka é famoso pela floração espetacular de crocus na primavera", "Regista uma das maiores populações de lince dos Cárpatos nos Beskides"],
      fr: ["L'animal emblématique du parc, la salamandre tachetée, est extrêmement fréquent ici", "Le plus haut sommet du parc national est le Turbacz boisé, avec 1 310 mètres", "Plus de 50 ruisseaux de montagne préservés traversent les pentes boisées du parc", "Abrite des populations denses de grands tétras et de gélinottes des bois sur les crêtes", "Les anciennes cabanes de bergers en bois (« Szałasy ») témoignent de l'histoire culturelle valaque", "La prairie de montagne Jaworzyna Kamienicka est célèbre pour sa spectaculaire floraison de crocus printaniers", "Enregistre l'une des plus grandes populations de lynx des Carpates dans les Beskides"],
