      es: ["El impetuoso Drawa es venerado por los piragüistas como una de las mejores rutas de aguas bravas de Polonia", "El parque protege 20 lagos glaciares, incluido el lago Czarne, extremadamente profundo y oscuro", "Alberga poblaciones relictas de la rara trucha común y el tímalo europeo", "El logotipo del parque muestra con orgullo a la nutria euroasiática en su elemento natural", "Contiene los restos del muro histórico 'Pommernwall' de la Segunda Guerra Mundial", "Una densidad excepcionalmente alta de martines pescadores anidando a lo largo de las riberas", "El cauce del río, profundamente encajado, genera un microclima fresco y húmedo totalmente aislado"],
      pt: ["O impetuoso Drawa é venerado pelos canoístas como uma das melhores rotas de águas bravas da Polónia", "O parque protege 20 lagos glaciares, incluindo o lago Czarne, extremamente profundo e escuro", "Abriga populações relíquias da rara truta-comum e do tímalo-europeu", "O logótipo do parque mostra com orgulho a lontra euroasiática no seu elemento natural", "Contém os restos da histórica muralha 'Pommernwall' da Segunda Guerra Mundial", "Uma densidade excecionalmente alta de guarda-rios a nidificar ao longo das margens", "O curso do rio profundamente escavado gera um microclima fresco e húmido isolado"],
